// AsBuildpackBuild returns the union data inside the Build as a BuildpackBuild
func (t Build) AsBuildpackBuild() (BuildpackBuild, error) {
	var body BuildpackBuild
	err := json.Unmarshal(t.union, &body)
	return body, err
}

// FromBuildpackBuild overwrites any union data inside the Build as the provided BuildpackBuild
func (t *Build) FromBuildpackBuild(v BuildpackBuild) error {
	v.Type = "buildpack"
	b, err := json.Marshal(v)
	t.union = b
	return err
}

// MergeBuildpackBuild performs a merge with any union data inside the Build, using the provided BuildpackBuild
func (t *Build) MergeBuildpackBuild(v BuildpackBuild) error {
	v.Type = "buildpack"
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}

	merged, err := runtime.JSONMerge(t.union, b)
	t.union = merged
	return err
}

